import type { RichTextProps } from "./rich-text.types";

import { forwardRef, useEffect } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Plate, usePlateEditor } from "platejs/react";

import { RichTextClasses, StyledRichText } from "./rich-text.styles";
import {
  RichTextToolbar,
  RichTextFloatingToolbar,
  RichTextContent,
  RichTextLinkInsertToolbar,
  RichTextLinkEditToolbar,
  RichTextFloatingLinkToolbar,
} from "./subcomponents";

const RichTextRoot = forwardRef(
  (
    {
      className,
      variant = "default",
      children,
      editor: externalEditor,
      onChange,
      readOnly = false,
      styleSlots,
      ...props
    }: RichTextProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme(),
      rootClasses = clsx(RichTextClasses.root, className);

    // Bare internal editor if omitted — disabled when an external editor is provided
    const internalEditor = usePlateEditor({ enabled: !externalEditor });

    useEffect(() => {
      if (!externalEditor && process.env.NODE_ENV !== "production") {
        // eslint-disable-next-line no-console
        console.warn(
          "RichText: 'editor' prop was omitted. A bare editor is being used internally without any plugins. " +
            "In production, you should provide a fully configured PlateEditor.",
        );
      }
    }, [externalEditor]);

    const activeEditor = externalEditor || internalEditor;

    return (
      <Plate
        editor={activeEditor}
        readOnly={readOnly}
        onChange={({ value: newValue }) => {
          if (onChange) {
            onChange(newValue);
          }
        }}
      >
        <StyledRichText
          ref={ref}
          className={rootClasses}
          currentTheme={theme}
          data-readonly={readOnly || undefined}
          styleSlots={styleSlots}
          variant={variant}
          {...props}
        >
          {children}
        </StyledRichText>
      </Plate>
    );
  },
);

RichTextRoot.displayName = "RichText";

const RichText = Object.assign(RichTextRoot, {
  Toolbar: RichTextToolbar,
  FloatingToolbar: RichTextFloatingToolbar,
  Content: RichTextContent,
  LinkInsertToolbar: RichTextLinkInsertToolbar,
  LinkEditToolbar: RichTextLinkEditToolbar,
  FloatingLinkToolbar: RichTextFloatingLinkToolbar,
});

export default RichText;
